SELECT 'batch_027_28afc804_wav_11' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-313044d5-8e7','sm-upload-56bf2361-db0','sm-upload-5ccdcea5-f34','sm-upload-705493af-48f','sm-upload-795396d6-0dc','sm-upload-7c38c335-00f','sm-upload-88b0c03f-c5d','sm-upload-b4d0e9bd-ff0','sm-upload-debcd1ae-909','sm-upload-e4a10341-0e6','sm-upload-eebc0991-9f4') AND album_id='al-d661f426bd5bde71baa8114128afc804') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-313044d5-8e7','sm-upload-56bf2361-db0','sm-upload-5ccdcea5-f34','sm-upload-705493af-48f','sm-upload-795396d6-0dc','sm-upload-7c38c335-00f','sm-upload-88b0c03f-c5d','sm-upload-b4d0e9bd-ff0','sm-upload-debcd1ae-909','sm-upload-e4a10341-0e6','sm-upload-eebc0991-9f4') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-d661f426bd5bde71baa8114128afc804' AND name='赏味期限') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-d661f426bd5bde71baa8114128afc804') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-d661f426bd5bde71baa8114128afc804') AS calculated_size;
